after.content:
  const signatures = [];
  for (const className of classes) {
    const output = execFileSync("javap", ["-public", "-classpath", path.join(libs, jar), className], { encoding: "utf8" });
    const lines = output.split(/\r?\n/)
      .map(line => line.trim())
      .filter(line => line && !line.startsWith("Compiled from") && line !== "{" && line !== "}")
      .map(line => line.replace(/;$/, ""));
    if (!lines[0]?.match(/^public (?:class|final class|abstract class|interface|record|enum|sealed interface|non-sealed )/)) continue;
    signatures.push(...lines);
  }
  inventory.modules[name] = [...new Set(signatures)].sort();
}
